xql_query:
// ============================================================
// Rule: LNX_Unexpected Process Running su for Privilege Escalation
// Vendor: Linux
// Objective:
// Detect activity associated with LNX_Unexpected Process Running su for Privilege Escalation.
// Severity: SEV_040_HIGH
// Category: PRIVILEGE_ESCALATION
// ============================================================

dataset = xdr_data

// Seleciona apenas os campos relevantes para investigação e contexto do evento
| fields 
    _time,
    agent_hostname,
    agent_os_type,
    event_type,
    event_sub_type,
    actor_effective_username,
    actor_effective_user_sid,
    actor_process_image_path,
    actor_process_image_name,
    actor_process_command_line,
    actor_process_image_sha256,
    action_process_image_name,
    action_process_image_command_line,
    action_process_user_sid

// Filtra eventos de criação/início de processo em hosts Linux
| filter 
    event_type = ENUM.PROCESS
    and event_sub_type = ENUM.PROCESS_START
    and agent_os_type = ENUM.AGENT_OS_LINUX

    // Exclui execuções onde o usuário efetivo é root
    // UID 0 representa o usuário root em sistemas Linux
    and actor_effective_user_sid != "0"

    // Identifica tentativas de execução do comando "su"
    // O foco é detectar quando um processo não esperado tenta iniciar troca de usuário
    and (
        // Caso direto: processo "su" sendo executado com comando "su" ou "/usr/bin/su"
        (
            action_process_image_name = "su"
            and action_process_image_command_line in ("su", "/usr/bin/su")
        )

        or

        // Caso indireto: shell executando "su" via parâmetro "-c"
        // Exemplo: bash -c su ou sh -c su
        (
            action_process_image_name in ("bash", "sh")
            and action_process_image_command_line ~= "-c(?:\\s--)?\\ssu$"
        )
    )

    // Exclui processos pais comuns e esperados para execução de comandos/shells
    // A ideia é destacar binários incomuns tentando acionar "su"
    and actor_process_image_name not in (
        "bash",
        "sh",
        "zsh",
        "ksh",
        "sudo",
        "su"
    )

// Consolida os eventos por host, processo pai e hash do processo pai
// Isso reduz ruído e facilita análise por comportamento recorrente
| comp 
    earliest(_time) as first_seen,
    latest(_time) as last_seen,
    count() as execution_count,
    values(actor_effective_username) as actor_usernames,
    values(actor_process_image_path) as actor_image_paths,
    values(actor_process_command_line) as actor_cmd_lines,
    values(action_process_image_command_line) as action_cmd_lines,
    values(action_process_user_sid) as action_UIDs
by 
    agent_hostname,
    actor_process_image_name,
    actor_process_image_sha256
